package model

type User struct {
	UUID      string `json:"uid" db:"uid" valid:"-"`
	Email     string `json:"email" db:"email" valid:"required,email"`
	Password  string `json:"password" db:"password" valid:"-"`
	FirstName string `json:"first_name" db:"first_name" valid:"-"`
	LastName  string `json:"last_name" db:"last_name" valid:"-"`
	CreatedAt string `json:"-" db:"created_at" valid:"-"`
}

type Login struct {
	Email    string `json:"email" db:"email" valid:"required,email"`
	Password string `json:"password" db:"password" valid:"-"`
}

package main

import "auth/cmd"

func main() {
	cmd.Execute()
}

package services

import (
	"auth/internal/services/users"

	"go.uber.org/zap"
)

type Auth struct {
	UsrSvc users.Service
	Log    *zap.Logger
}

package users

import (
	"auth/internal/model"
	"context"
)

type Service interface {
	UserLogin(ctx context.Context, l *model.Login, ss *model.Session) error
	UserRegistration(ctx context.Context, u *model.User, ss *model.Session) error
}
